import csv, math
p='/root/data/stock-descriptions.csv'
with open(p,newline='',encoding='utf-8') as f:
    r=csv.DictReader(f)
    rows=list(r)
print('rows',len(rows))
print('columns',r.fieldnames)
sectors={}
missing=[]
